; Pyramids of Ra (U) - sound driver and data, bank $02 $4000-$7FFF
; Generated by tools/gen_ra.py. Assembles byte-identical with RGBDS 1.0.0.

INCLUDE "hardware.inc"
INCLUDE "ra_sound.inc"

; ---- WRAM ----
DEF wRaPtrCh4              EQU $C4EF	; event pointers (ch4 noise, ch2, ch1, ch3 = loaded but never used)
DEF wRaPtrCh2              EQU $C4F1
DEF wRaPtrCh1              EQU $C4F3
DEF wRaPtrCh3              EQU $C4F5
DEF wRaInstCh1             EQU $C4F9	; always 0: program changes are skipped
DEF wRaTransposeCh1        EQU $C4FA
DEF wRaCh1NR12             EQU $C4FB
DEF wRaCh1NR10             EQU $C4FC
DEF wRaCh1NR11             EQU $C4FD
DEF wRaSfxTimer            EQU $C4FE	; SFX frames left
DEF wRaSfxNote             EQU $C4FF	; SFX note index (instrument byte 3)
DEF wRaCh1FreqLo           EQU $C500
DEF wRaCh1VibPattern       EQU $C501
DEF wRaCh1VibStep          EQU $C502
DEF wRaCh1VibMask          EQU $C503
DEF wRaInstCh2             EQU $C504
DEF wRaTransposeCh2        EQU $C505
DEF wRaCh2NR22             EQU $C506
DEF wRaCh2NR10             EQU $C507	; loaded, unused
DEF wRaCh2NR21             EQU $C508
DEF wRaCh2Note             EQU $C509	; loaded, unused
DEF wRaCh2Len              EQU $C50A	; loaded, unused
DEF wRaCh2FreqLo           EQU $C50B
DEF wRaCh2VibPattern       EQU $C50C
DEF wRaCh2VibStep          EQU $C50D
DEF wRaCh2VibMask          EQU $C50E
DEF wRaSfxActive           EQU $C50F	; $FF while an SFX owns ch1
DEF wRaMusicOn             EQU $C510	; game copies its music option here every frame
DEF wRaSndEnabled          EQU $C511	; 0 = driver does nothing (game flag)
DEF wRaTickCount           EQU $C512	; free-running; masked for the vibrato rate
DEF wRaClockHi             EQU $C513	; 12-bit position in the bar, hi
DEF wRaClockLo             EQU $C514	; ... lo; wraps at $2FC
DEF wRaBar                 EQU $C515	; bar counter
DEF wRaSongBars            EQU $C516	; bars in the song; reaching it restarts the song
DEF wRaSong                EQU $C517
DEF wRaTicksPerFrame       EQU $C518	; clock ticks run per frame

SECTION "Pyramids of Ra sound", ROMX[$4000], BANK[$02]

RaSnd_PlaySong:
	ld [wRaSong],a	; a = song id
	ld e,a
	sla a
	sla a
	sla a
	sla e
	sla e
	add a,e
	ld d,$00
	ld e,a
	ld hl,RaSongTable
	add hl,de
	ld a,[hli]
	ld [wRaPtrCh4],a
	ld a,[hli]
	ld [wRaPtrCh4+1],a
	ld a,[hli]
	ld [wRaPtrCh2],a
	ld a,[hli]
	ld [wRaPtrCh2+1],a
	ld a,[hli]
	ld [wRaPtrCh1],a
	ld a,[hli]
	ld [wRaPtrCh1+1],a
	ld a,[hli]
	ld [wRaPtrCh3],a
	ld a,[hli]
	ld [wRaPtrCh3+1],a
	ld a,[hli]
	ld [wRaTicksPerFrame],a
	ld a,[hli]
	ld [wRaSongBars],a
	ld a,[hli]
	ld [wRaTransposeCh1],a
	ld a,[hli]
	ld [wRaTransposeCh2],a
	xor a
	ld [wRaInstCh1],a
	ld [wRaInstCh2],a
	ld [wRaClockHi],a
	ld [wRaClockLo],a
	ld [wRaBar],a
	ld a,$77
	ldh [rNR50],a
	ld a,$93
	ldh [rNR51],a
	ld a,$8F
	ldh [rNR52],a
	ld a,$FF
	ld [wRaMusicOn],a
	ret

; 12 bytes per song: ch4 events, ch2 events, ch1 events, ch3 (unused),
; ticks per frame, bars, ch1 transpose, ch2 transpose
RaSongTable:
	song_header RaSong0_Ch4, RaSong0_Ch2, RaSong0_Ch1, 0, 9, 40, $2A, $1E	; song 0
	song_header RaSong1_Ch4, RaSong1_Ch2, RaSong1_Ch1, 0, 9, 32, $2A, $1E	; song 1
	song_header RaSong2_Ch4, RaSong2_Ch4, RaSong2_Ch4, 0, 8, 24, $1F, $1F	; song 2
	song_header RaSong2_Ch4, RaSong3_Ch2, RaSong3_Ch1, 0, 9, 40, $24, $24	; song 3
	song_header RaSong4_Ch4, RaSong4_Ch2, RaSong4_Ch1, 0, 9, 4, $24, $24	; song 4

RaSnd_Update:
	ld a,[wRaSndEnabled]
	and a
	jr z, .done
	call RaSnd_SfxTimer
	ld a,[wRaTicksPerFrame]
	ld b,a
.tick:
	ld hl,$C512
	inc [hl]
	ld a,[wRaMusicOn]
	and a
	jr z, .vibrato
	call RaSnd_Ch1Events
	call RaSnd_Ch2Events
	call RaSnd_Ch4Events
	call RaSnd_AdvanceClock
.vibrato:
	call RaSnd_Ch1Vibrato
	call RaSnd_Ch2Vibrato
	dec b
	jr nz, .tick
.done:
	ret
RaSnd_StopMusic:
	xor a
	ld [wRaMusicOn],a
	ret
RaSnd_Ch1Events:
	push bc
.loop:
	ld a,[wRaPtrCh1]
	ld e,a
	ld a,[wRaPtrCh1+1]
	ld d,a
	ld hl,1
	call RaSnd_CmpTick
	jr nz, .done
	ld hl,0
	call RaSnd_CmpBar
	jr nz, .done
	ld a,[wRaSfxActive]
	and a
	jr nz, .next
	ld hl,3
	add hl,de
	ld a,[hl]
	cp $01	; status $01 on ch1 = stop music (unused in data)
	jr z, RaSnd_StopMusic
	cp $74	; status $74 = park this track (unused in data)
	jr z, .done
	and $F0
	cp $C0	; program change: ignored
	jr z, .progChange
	call RaSnd_LoadCh1Inst
	ld a,[wRaCh1NR10]
	ldh [rNR10],a
	ld a,[wRaCh1NR11]
	ldh [rNR11],a
	ld a,[wRaCh1NR12]
	ldh [rNR12],a
	ld hl,4
	add hl,de
	ld a,[hl]
	ld hl,$C4FA
	sub [hl]
	jr c, .next
	sla a
	ld b,$00
	ld c,a
	ld hl,RaFreqTable	; note - transpose; below 0 = skipped
	add hl,bc
	ld a,[hli]
	ldh [rNR13],a
	ld [wRaCh1FreqLo],a
	ld a,[hli]
	or $80
	ldh [rNR14],a
.next:
	ld hl,5
	add hl,de
	ld a,l
	ld [wRaPtrCh1],a
	ld a,h
	ld [wRaPtrCh1+1],a
	jr .loop
.done:
	pop bc
	ret
.progChange:
	ld hl,4
	add hl,de
	ld a,[hl]
	jr .next
RaSnd_Ch1Vibrato:
	ld a,[wRaTickCount]
	ld hl,$C503
	and [hl]
	jr nz, .done
	ld hl,$C501
	rrc [hl]
	jr nc, .down
	ld a,[wRaCh1FreqLo]
	ld hl,$C502
	add a,[hl]
	ld [wRaCh1FreqLo],a
	ld [wRaCh1FreqLo],a	; (stored twice)
	ldh [rNR13],a
	jr .done
.down:
	ld a,[wRaCh1FreqLo]
	ld hl,$C502
	sub [hl]
	ld [wRaCh1FreqLo],a
	ldh [rNR13],a
.done:
	ret
RaSnd_LoadCh1Inst:
	ld a,[wRaInstCh1]
RaSnd_LoadInst:
	sla a
	ld b,$00
	ld c,a
	ld hl,RaInstTable
	add hl,bc
	ld a,[hli]
	ld h,[hl]
	ld l,a
	ld a,[hli]
	ld [wRaCh1NR12],a
	ld a,[hli]
	ld [wRaCh1NR10],a
	ld a,[hli]
	ld [wRaCh1NR11],a
	ld a,[hli]
	ld [wRaSfxNote],a
	ld a,[hli]
	ld [wRaSfxTimer],a
	ld a,[hli]
	ld [wRaCh1VibPattern],a
	ld a,[hli]
	ld [wRaCh1VibStep],a
	ld a,[hli]
	ld [wRaCh1VibMask],a
	ret
RaSnd_Ch2Events:
	push bc
.loop:
	ld a,[wRaPtrCh2]
	ld e,a
	ld a,[wRaPtrCh2+1]
	ld d,a
	ld hl,1
	call RaSnd_CmpTick
	jr nz, .done
	ld hl,0
	call RaSnd_CmpBar
	jr nz, .done
	ld hl,3
	add hl,de
	ld a,[hl]
	cp $74
	jr z, .done
	and $F0
	cp $C0
	jr z, .progChange
	call RaSnd_LoadCh2Inst
	ld a,[wRaCh2NR21]
	ldh [rNR21],a
	ld a,[wRaCh2NR22]
	ldh [rNR22],a
	ld hl,4
	add hl,de
	ld a,[hl]
	ld hl,$C505
	sub [hl]
	jr c, .next
	sla a
	ld b,$00
	ld c,a
	ld hl,RaFreqTable
	add hl,bc
	ld a,[hli]
	ldh [rNR23],a
	ld [wRaCh2FreqLo],a
	ld a,[hli]
	or $80
	ldh [rNR24],a
.next:
	ld hl,5
	add hl,de
	ld a,l
	ld [wRaPtrCh2],a
	ld a,h
	ld [wRaPtrCh2+1],a
	jr .loop
.done:
	pop bc
	ret
.progChange:
	ld hl,4
	add hl,de
	ld a,[hl]
	jr .next
RaSnd_Ch2Vibrato:
	ld a,[wRaTickCount]
	ld hl,$C50E
	and [hl]
	jr nz, .done
	ld hl,$C50C
	rrc [hl]
	jr nc, .down
	ld a,[wRaCh2FreqLo]
	ld hl,$C50D
	add a,[hl]
	ld [wRaCh2FreqLo],a
	ld [wRaCh2FreqLo],a	; (stored twice)
	ldh [rNR23],a
	jr .done
.down:
	ld a,[wRaCh2FreqLo]
	ld hl,$C50D
	sub [hl]
	ld [wRaCh2FreqLo],a
	ldh [rNR23],a
.done:
	ret
RaSnd_LoadCh2Inst:
	ld a,[wRaInstCh2]
	sla a
	ld b,$00
	ld c,a
	ld hl,RaInstTable
	add hl,bc
	ld a,[hli]
	ld h,[hl]
	ld l,a
	ld a,[hli]
	ld [wRaCh2NR22],a
	ld a,[hli]
	ld [wRaCh2NR10],a
	ld a,[hli]
	ld [wRaCh2NR21],a
	ld a,[hli]
	ld [wRaCh2Note],a
	ld a,[hli]
	ld [wRaCh2Len],a
	ld a,[hli]
	ld [wRaCh2VibPattern],a
	ld a,[hli]
	ld [wRaCh2VibStep],a
	ld a,[hli]
	ld [wRaCh2VibMask],a
	ret
RaSnd_Ch4Events:
	push bc
.loop:
	ld a,[wRaPtrCh4]
	ld e,a
	ld a,[wRaPtrCh4+1]
	ld d,a
	ld hl,1
	call RaSnd_CmpTick
	jr nz, .done
	ld hl,0
	call RaSnd_CmpBar
	jr nz, .done
	ld hl,3
	add hl,de
	ld a,[hl]
	ld hl,4
	add hl,de
	ld a,[hl]
	sub $48	; drum notes $48-$53 pick a length
	ld hl,RaNoiseLenTable
	ld b,$00
	ld c,a
	add hl,bc
	ld a,[hl]
	ldh [rNR41],a
	ld a,$F9	; NR42: vol 15, "increase"
	ldh [rNR42],a
	ld a,$17	; NR43
	ldh [rNR43],a
	ld a,$C0	; trigger + length enable
	ldh [rNR44],a
	ld hl,5
	add hl,de
	ld a,l
	ld [wRaPtrCh4],a
	ld a,h
	ld [wRaPtrCh4+1],a
	jr .loop
.done:
	pop bc
	ret
RaSnd_AdvanceClock:
	ld hl,$C514
	inc [hl]
	jr nz, .checkBar
	ld hl,$C513
	inc [hl]
.checkBar:
	ld a,[wRaClockHi]
	cp $02	; bar = $2FC ticks (ticks $2FC-$2FF never happen)
	jr nz, .done
	ld a,[wRaClockLo]
	cp $FC
	jr nz, .done
	xor a
	ld [wRaClockHi],a
	ld [wRaClockLo],a
	ld hl,$C515
	inc [hl]
	ld a,[wRaSongBars]
	cp [hl]
	jr nz, .done
	ld a,[wRaSong]
	call RaSnd_PlaySong
.done:
	ret
RaSnd_CmpBar:
	add hl,de
	ld a,[hli]
	sla a
	sla a
	sla a
	sla a
	ld c,a
	ld a,[hli]
	srl a
	srl a
	srl a
	srl a
	or c
	ld hl,$C515
	cp [hl]
	ret
RaSnd_CmpTick:
	add hl,de
	ld a,[hli]
	and $0F
	ld c,a
	ld a,[wRaClockHi]
	cp c
	jr nz, .done
	ld a,[hli]
	ld c,a
	ld a,[wRaClockLo]
	cp c
.done:
	ret
RaSnd_PlaySfx:
	ld c,a	; a = SFX id = instrument number
	ld a,[wRaSfxActive]
	and a
	jr nz, .done
	ld a,c
	call RaSnd_LoadInst
	ld a,[wRaCh1NR10]
	ldh [rNR10],a
	ld a,[wRaCh1NR11]
	ldh [rNR11],a
	ld a,[wRaCh1NR12]
	ldh [rNR12],a
	ld a,[wRaSfxNote]
	sla a
	ld hl,RaFreqTable
	ld b,$00
	ld c,a
	add hl,bc
	ld a,[hli]
	ldh [rNR13],a
	ld [wRaCh1FreqLo],a
	ld a,[hli]
	or $80
	ldh [rNR14],a
	ld a,$FF
	ld [wRaSfxActive],a
.done:
	ret
RaSnd_SfxTimer:
	ld a,[wRaSfxActive]
	and a
	jr z, .done
	ld hl,$C4FE
	dec [hl]
	jr nz, .done
	xor a
	ld [wRaSfxActive],a
.done:
	ret

; NR41 length for drum notes $48-$53 (ch4 only plays one noise, NR42=$F9 NR43=$17)
RaNoiseLenTable:
	db $3D, $3C, $3E, $3C, $3C, $3C, $3C, $3C, $3C, $3C, $3C, $3C

; Frequency table, indexed by (MIDI note - transpose). Entries 0-5 are 0; 6 = C2 ... 53 = B5.
RaFreqTable:
	dw $0000, $0000, $0000, $0000, $0000, $0000, $002C, $009D
	dw $0107, $016B, $01CA, $0223, $0277, $02C7, $0312, $0359
	dw $039B, $03DA, $0416, $044E, $0483, $04B6, $04E5, $0511
	dw $053C, $0563, $0589, $05AC, $05CF, $05ED, $060B, $0627
	dw $0642, $065B, $0672, $0689, $069E, $06B1, $06C4, $06D6
	dw $06E7, $06F6, $0705, $0714, $0721, $072D, $0739, $0744
	dw $074F, $0759, $0762, $076B, $0773, $077B

; Instrument = SFX table. Music always uses instrument 0 (program changes are
; skipped); RaSnd_PlaySfx(a) plays instrument a on ch1.
RaInstTable:
	dw RaInst00, RaInst01, RaInst02, RaInst03
	dw RaInst04, RaInst05, RaInst06, RaInst07
	dw RaInst08, RaInst09, RaInst10, RaInst11
	dw RaInst12, RaInst13, RaInst14, RaInst15
	dw RaInst16, RaInst17, RaInst18, RaInst19
	dw RaInst20, RaInst21, RaInst22, RaInst23

; ra_inst NR12, NR10, NR11, SFX note index, SFX frames, vibrato pattern, vibrato step, vibrato rate mask
RaInst00:	ra_inst $F4, $00, $40, $00, $00, $CC, $02, $1F
RaInst01:	ra_inst $F2, $00, $80, $00, $00, $CC, $00, $0F
RaInst02:	ra_inst $F2, $17, $80, $28, $14, $CC, $1F, $07
RaInst03:	ra_inst $F7, $07, $80, $2D, $64, $CC, $28, $07
RaInst04:	ra_inst $F2, $07, $C0, $23, $1E, $CC, $1F, $07
RaInst05:	ra_inst $F2, $37, $C0, $21, $1E, $CC, $1F, $07
RaInst06:	ra_inst $F2, $2F, $C0, $24, $14, $CC, $19, $03
RaInst07:	ra_inst $FB, $27, $40, $26, $14, $F0, $0A, $1F
RaInst08:	ra_inst $FA, $37, $00, $29, $14, $F0, $14, $0F
RaInst09:	ra_inst $F4, $7F, $40, $30, $14, $F0, $14, $0F
RaInst10:	ra_inst $F4, $58, $00, $2A, $64, $55, $0A, $07
RaInst11:	ra_inst $F4, $58, $00, $16, $46, $55, $12, $1F
RaInst12:	ra_inst $F3, $38, $00, $1E, $46, $77, $02, $03
RaInst13:	ra_inst $F3, $38, $00, $24, $1E, $F6, $05, $07
RaInst14:	ra_inst $F2, $37, $C0, $00, $46, $CC, $1F, $07
RaInst15:	ra_inst $F2, $37, $C0, $23, $46, $CC, $1F, $07
RaInst16:	ra_inst $F4, $58, $00, $2A, $46, $55, $0A, $07
RaInst17:	ra_inst $F4, $00, $00, $28, $46, $00, $02, $03
RaInst18:	ra_inst $F7, $07, $80, $2D, $46, $CC, $28, $07
RaInst19:	ra_inst $0D, $7F, $00, $23, $46, $00, $14, $0F
RaInst20:	ra_inst $0D, $7F, $00, $23, $46, $00, $14, $0F
RaInst21:	ra_inst $85, $7F, $00, $32, $46, $E0, $10, $03
RaInst22:	ra_inst $F1, $7F, $00, $1E, $46, $00, $10, $07
RaInst23:	ra_inst $85, $7F, $00, $32, $23, $E0, $10, $03

